#!/bin/sh
set -eu
# Values generated by setup use hex. Reject unsafe SQL identifiers/literals.
case "$MYSQL_USER" in *[!a-zA-Z0-9_]*|'') echo 'Invalid MYSQL_USER' >&2; exit 1;; esac
case "$MYSQL_DATABASE" in *[!a-zA-Z0-9_]*|'') echo 'Invalid MYSQL_DATABASE' >&2; exit 1;; esac
case "$MYSQL_EXPORTER_PASSWORD" in *[!a-zA-Z0-9]*|'') echo 'Exporter password must be alphanumeric' >&2; exit 1;; esac
MYSQL_PWD="$MYSQL_ROOT_PASSWORD" mysql --protocol=socket -uroot <<SQL
REVOKE ALL PRIVILEGES, GRANT OPTION FROM '${MYSQL_USER}'@'%';
GRANT SELECT, INSERT, UPDATE, DELETE ON \`${MYSQL_DATABASE}\`.* TO '${MYSQL_USER}'@'%';
CREATE USER 'exporter'@'%' IDENTIFIED BY '${MYSQL_EXPORTER_PASSWORD}' WITH MAX_USER_CONNECTIONS 3;
GRANT PROCESS, REPLICATION CLIENT, SELECT ON *.* TO 'exporter'@'%';
SQL
